 *
 * HLK-LD2450 frame parser implementation.
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include "ld2450_parser.h"

#include <string.h>

/* Frame layout (see header for the protocol description). */

#define HDR0 0xAA
#define HDR1 0xFF
#define TYPE 0x03
#define LEN0 0x00
#define FTR0 0x55
#define FTR1 0xCC

enum ld2450_state
{
  ST_IDLE = 0,
  ST_HDR0,
  ST_HDR1,
  ST_TYPE,
  ST_LEN,
  ST_PAYLOAD,      /* absorbing LD2450_TARGETS_MAX * LD2450_TARGET_LEN */
  ST_FTR0,
  ST_FTR1
};

static void decode_target(const uint8_t *t, struct ld2450_target *out)
{
  out->x_mm       = (int16_t)(t[0] | (t[1] << 8));
  out->y_mm       = (int16_t)(t[2] | (t[3] << 8));
  out->speed_cmps = (int16_t)(t[4] | (t[5] << 8));
  out->resolution = t[6];
  out->distance   = t[7];
  out->valid      = (out->x_mm != 0 || out->y_mm != 0);
}

void ld2450_parser_reset(struct ld2450_parser *p)
{
  p->len = 0;
  p->buf[0] = 0;
}

int ld2450_parser_feed(struct ld2450_parser *p, uint8_t byte,
                       struct ld2450_frame *frame)
{
  enum ld2450_state st;
  size_t need;

  st = (p->len == 0) ? ST_IDLE : (enum ld2450_state)p->buf[0];
  p->buf[1] = byte;

  switch (st)
    {
      case ST_IDLE:
        if (byte == HDR0)
          {
            p->buf[0] = ST_HDR0;
            p->len = 2;
          }
        break;

      case ST_HDR0:
        if (byte == HDR1)
          {
            p->buf[0] = ST_HDR1;
            p->len = 3;
          }
        else
          {
            ld2450_parser_reset(p);
          }
        break;

      case ST_HDR1:
        if (byte == TYPE)
          {
            p->buf[0] = ST_TYPE;
            p->len = 4;
          }
        else
          {
            ld2450_parser_reset(p);
          }
        break;

      case ST_TYPE:
        if (byte == LEN0)
          {
            p->buf[0] = ST_LEN;
            p->len = 5;
          }
        else
          {
            ld2450_parser_reset(p);
          }
        break;

      case ST_LEN:
        p->buf[0] = ST_PAYLOAD;
        p->len = 6;
        break;

      case ST_PAYLOAD:
        need = 1 + LD2450_TARGETS_MAX * LD2450_TARGET_LEN;
        if (p->len < need)
          {
            p->len++;
          }

        if (p->len == need)
          {
            p->buf[0] = ST_FTR0;
            p->len++;
          }
        break;

      case ST_FTR0:
        if (byte == FTR0)
          {
            p->buf[0] = ST_FTR1;
            p->len++;
          }
        else
          {
            ld2450_parser_reset(p);
          }
        break;

      case ST_FTR1:
        if (byte == FTR1)
          {
            const uint8_t *t = p->buf + 2;   /* payload starts at buf[2] */
            int i;

            for (i = 0; i < LD2450_TARGETS_MAX; i++)
              {
                decode_target(t + i * LD2450_TARGET_LEN,
                              &frame->targets[i]);
              }

            ld2450_parser_reset(p);
            return 1;
          }
        else
          {
            ld2450_parser_reset(p);
          }
        break;

      default:
        ld2450_parser_reset(p);
        break;
    }

  return 0;
}

int ld2450_parse_frame(const uint8_t *data, size_t len,
                       struct ld2450_frame *frame)
{
  struct ld2450_parser p;
  size_t i;

  ld2450_parser_reset(&p);

  for (i = 0; i < len; i++)
    {
      if (ld2450_parser_feed(&p, data[i], frame))
        {
          return 1;
        }
    }

  return 0;
}

