  struct ld2450_parser p;
  size_t i;

  ld2450_parser_reset(&p);

  for (i = 0; i < len; i++)
    {
      if (ld2450_parser_feed(&p, data[i], frame))
        {
          return 1;
        }
    }

  return 0;
}

/****************************************************************************
 * ai-apps/mapping/lamp_map.h
 *
 * Lamp position map + nearest-lamp lookup ("stand under the lamp" rule).
 *
 * Room coordinates: mm, origin at the radar.  Lamps are registered once
 * at startup (calibration).  The lookup returns the nearest enabled lamp
 * within a threshold distance -- the M3 V1 "站灯开灯" rule engine.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef AI_APPS_MAPPING_LAMP_MAP_H
#define AI_APPS_MAPPING_LAMP_MAP_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C"
{
#endif

#define LAMP_MAP_MAX_LAMPS 16

struct lamp
{
  int   id;        /* lamp id (relay channel id) */
  int   x_mm;      /* room x, mm */
  int   y_mm;      /* room y, mm */
  bool  enabled;
};

struct lamp_map
{
  struct lamp lamps[LAMP_MAP_MAX_LAMPS];
  size_t count;
};

/* Reset the map (no lamps). */
void lamp_map_reset(struct lamp_map *m);

/* Add/overwrite a lamp by id.  Returns 0 on success, -1 if full. */
int lamp_map_register(struct lamp_map *m, int id, int x_mm, int y_mm);

/* Set/clear a lamp's enabled state. */
void lamp_map_set_enabled(struct lamp_map *m, int id, bool enabled);

/* Nearest enabled lamp to (x, y), within max_dist_mm.
 * Returns the lamp id, or -1 if none.  Also reports the distance. */
int lamp_map_find_nearest(const struct lamp_map *m, int x_mm, int y_mm,
                          int max_dist_mm, int *dist_mm);

/* Euclidean distance between two points, mm. */
int lamp_map_dist(int ax, int ay, int bx, int by);

#ifdef __cplusplus
}
#endif

#endif /* AI_APPS_MAPPING_LAMP_MAP_H */

/****************************************************************************
 * ai-apps/mapping/lamp_map.c
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include "lamp_map.h"

#include <stdlib.h>

void lamp_map_reset(struct lamp_map *m)
{
  m->count = 0;
}

int lamp_map_register(struct lamp_map *m, int id, int x_mm, int y_mm)
{
  size_t i;

  for (i = 0; i < m->count; i++)
    {
      if (m->lamps[i].id == id)
        {
          m->lamps[i].x_mm     = x_mm;
          m->lamps[i].y_mm     = y_mm;
          m->lamps[i].enabled  = true;
          return 0;
        }
    }

  if (m->count >= LAMP_MAP_MAX_LAMPS)
    {
      return -1;
    }

  m->lamps[m->count].id      = id;
  m->lamps[m->count].x_mm    = x_mm;
  m->lamps[m->count].y_mm    = y_mm;
  m->lamps[m->count].enabled = true;
  m->count++;
  return 0;
}

void lamp_map_set_enabled(struct lamp_map *m, int id, bool enabled)
{
  size_t i;

  for (i = 0; i < m->count; i++)
    {
      if (m->lamps[i].id == id)
        {
          m->lamps[i].enabled = enabled;
          return;
        }
    }
}

int lamp_map_dist(int ax, int ay, int bx, int by)
{
  long dx = (long)ax - bx;
  long dy = (long)ay - by;

  return (int)labs((long)llround(sqrt((double)(dx * dx + dy * dy))));
}

int lamp_map_find_nearest(const struct lamp_map *m, int x_mm, int y_mm,
                          int max_dist_mm, int *dist_mm)
{
  int best_id  = -1;
  int best_d   = max_dist_mm;
  size_t i;

  for (i = 0; i < m->count; i++)
    {
      int d;

      if (!m->lamps[i].enabled)
        {
          continue;
        }

      d = lamp_map_dist(x_mm, y_mm, m->lamps[i].x_mm, m->lamps[i].y_mm);

      if (d < best_d)
        {
          best_d  = d;
          best_id = m->lamps[i].id;
        }
    }

  if (best_id >= 0 && dist_mm != NULL)
    {
      *dist_mm = best_d;
    }

  return best_id;
}

/****************************************************************************
 * ai-apps/mapping/lamp_map.c
 *
 * Integer-only implementation (no libm) so the module is directly
 * usable in the openvela user space / uORB driver.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include "lamp_map.h"

/* Squared distance (mm^2) between two points, in 64-bit to avoid
 * overflow with realistic room sizes (< 10 m). */
static long long dist_sq(int ax, int ay, int bx, int by)
{
  long long dx = (long long)ax - bx;
  long long dy = (long long)ay - by;

  return dx * dx + dy * dy;
}

void lamp_map_reset(struct lamp_map *m)
{
  m->count = 0;
}

int lamp_map_register(struct lamp_map *m, int id, int x_mm, int y_mm)
{
  size_t i;

  for (i = 0; i < m->count; i++)
    {
      if (m->lamps[i].id == id)
        {
          m->lamps[i].x_mm     = x_mm;
          m->lamps[i].y_mm     = y_mm;
          m->lamps[i].enabled  = true;
          return 0;
        }
    }

  if (m->count >= LAMP_MAP_MAX_LAMPS)
    {
      return -1;
    }

  m->lamps[m->count].id      = id;
  m->lamps[m->count].x_mm    = x_mm;
  m->lamps[m->count].y_mm    = y_mm;
  m->lamps[m->count].enabled = true;
  m->count++;
  return 0;
}

void lamp_map_set_enabled(struct lamp_map *m, int id, bool enabled)
{
  size_t i;

  for (i = 0; i < m->count; i++)
    {
      if (m->lamps[i].id == id)
        {
          m->lamps[i].enabled = enabled;
          return;
        }
    }
}

/* Integer square root (bit-by-bit method), exact for d < 2^31. */
static int isqrt(long long d)
{
  long long r = 0;
  long long bit = 1LL << 30;

  while (bit > d)
    {
      bit >>= 2;
    }

  while (bit != 0)
    {
      if (d >= r + bit)
        {
          d -= r + bit;
          r = (r >> 1) + bit;
        }
      else
        {
          r >>= 1;
        }

      bit >>= 2;
    }

  return (int)r;
}

int lamp_map_dist(int ax, int ay, int bx, int by)
{
  return isqrt(dist_sq(ax, ay, bx, by));
}

int lamp_map_find_nearest(const struct lamp_map *m, int x_mm, int y_mm,
                          int max_dist_mm, int *dist_mm)
{
  long long best_sq = (long long)max_dist_mm * max_dist_mm;
  long long found_sq = -1;
  int best_id = -1;
  size_t i;

  for (i = 0; i < m->count; i++)
    {
      long long d;

      if (!m->lamps[i].enabled)
        {
          continue;
        }

      d = dist_sq(x_mm, y_mm, m->lamps[i].x_mm, m->lamps[i].y_mm);

      if (d <= best_sq && (found_sq < 0 || d < found_sq))
        {
          found_sq = d;
          best_id  = m->lamps[i].id;
        }
    }

  if (best_id >= 0 && dist_mm != NULL)
    {
      *dist_mm = isqrt(found_sq);
    }

  return best_id;
}

/****************************************************************************
 * ai-apps/mapping/intent.h
 *
 * M3 V1 rule-engine intent state machine: KWS command words + radar
 * position -> lamp action.  No LLM involved (zero-LLM fallback tier).
 *
 * Flow:
 *   IDLE --word("开这个灯")--> AWAIT_POSITION --radar fix--> RESOLVED
 *   AWAIT_POSITION --timeout(T)--> IDLE (no lamp touched)
 *
 * Timeout keeps the full chain within the 1.5 s budget: words and
 * positions carry a monotonic millisecond timestamp supplied by the
 * caller (e.g. up_clock()/CLOCK_MONOTONIC on the target).
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef AI_APPS_MAPPING_INTENT_H
#define AI_APPS_MAPPING_INTENT_H

#include <stdbool.h>
#include <stdint.h>

#include "lamp_map.h"

#ifdef __cplusplus
extern "C"
{
#endif

#define INTENT_TIMEOUT_MS 1000   /* max wait for a radar fix */

enum intent_action
{
  INTENT_NONE = 0,
  INTENT_ON,        /* turn on the lamp nearest to the speaker */
  INTENT_OFF,       /* turn off the lamp nearest to the speaker */
  INTENT_ON_ALL,    /* turn on every lamp */
  INTENT_OFF_ALL    /* turn off every lamp */
};

struct intent_event
{
  enum intent_action action;
  int lamp_id;        /* valid when action is ON/OFF */
};

struct intent_engine
{
  enum intent_action pending;   /* action waiting for a position fix */
  int  state;                   /* 0 idle, 1 awaiting position */
  uint64_t deadline_ms;         /* timeout deadline, monotonic ms */
};

/* Reset the engine to idle. */
void intent_reset(struct intent_engine *e);

/* Feed a recognized command word (from Sherpa KWS).
 * Returns 1 if an intent_event was emitted immediately (ON_ALL/OFF_ALL),
 * 0 otherwise (position still needed). */
int intent_feed_word(struct intent_engine *e, const char *word,
                     uint64_t now_ms, struct intent_event *ev);

/* Feed a radar position fix (mm).  Resolves the pending action against
 * the lamp map; returns 1 and fills *ev on action, 0 otherwise. */
int intent_feed_position(struct intent_engine *e, int x_mm, int y_mm,
                         const struct lamp_map *m, int max_dist_mm,
                         uint64_t now_ms, struct intent_event *ev);

/* Called periodically (or on any tick) to expire pending actions. */
void intent_tick(struct intent_engine *e, uint64_t now_ms);

#ifdef __cplusplus
}
#endif

#endif /* AI_APPS_MAPPING_INTENT_H */

/****************************************************************************
 * ai-apps/mapping/intent.c
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include "intent.h"

#include <string.h>

/* Command word set (keep in sync with the Sherpa KWS keyword list). */

#define WORD_ON_THIS   "开这个灯"
#define WORD_ON        "开灯"
#define WORD_OFF       "关灯"
#define WORD_ON_ALL    "全部开灯"
#define WORD_OFF_ALL   "全部关灯"

void intent_reset(struct intent_engine *e)
{
  e->pending = INTENT_NONE;
  e->state   = 0;
  e->deadline_ms = 0;
}

static void expire(struct intent_engine *e)
{
  e->pending = INTENT_NONE;
  e->state   = 0;
}

int intent_feed_word(struct intent_engine *e, const char *word,
                     uint64_t now_ms, struct intent_event *ev)
{
  enum intent_action act = INTENT_NONE;

  if (strcmp(word, WORD_ON_THIS) == 0 || strcmp(word, WORD_ON) == 0)
    {
      act = INTENT_ON;
    }
  else if (strcmp(word, WORD_OFF) == 0)
    {
      act = INTENT_OFF;
    }
  else if (strcmp(word, WORD_ON_ALL) == 0)
    {
      act = INTENT_ON_ALL;
    }
  else if (strcmp(word, WORD_OFF_ALL) == 0)
    {
      act = INTENT_OFF_ALL;
    }

  if (act == INTENT_NONE)
    {
      return 0;
    }

  if (act == INTENT_ON_ALL || act == INTENT_OFF_ALL)
    {
      ev->action = act;
      ev->lamp_id = -1;
      return 1;
    }

  /* Position-dependent action: wait for a fresh radar fix. */
  e->pending = act;
  e->state   = 1;
  e->deadline_ms = now_ms + INTENT_TIMEOUT_MS;
  return 0;
}

int intent_feed_position(struct intent_engine *e, int x_mm, int y_mm,
                         const struct lamp_map *m, int max_dist_mm,
                         uint64_t now_ms, struct intent_event *ev)
{
  int lamp = -1;
  int dist = 0;

  if (e->state != 1 || e->pending == INTENT_NONE)
    {
      return 0;
    }

  if (now_ms >= e->deadline_ms)
    {
      expire(e);
      return 0;
    }

  lamp = lamp_map_find_nearest(m, x_mm, y_mm, max_dist_mm, &dist);

  if (lamp < 0)
    {
      /* No lamp within range: do not act on an empty guess. */
      expire(e);
      return 0;
    }

  ev->action = e->pending;
  ev->lamp_id = lamp;
  expire(e);
  return 1;
}

void intent_tick(struct intent_engine *e, uint64_t now_ms)
{
  if (e->state == 1 && now_ms >= e->deadline_ms)
    {
      expire(e);
    }
}

