/****************************************************************************
 * rt-agent/include/rt_msg.h
 *
 * RPMsg protocol between the openvela main system (A72/A53) and the
 * RK3576 built-in Cortex-M0 (rt-agent).
 *
 * Design constraints:
 *  - Shared memory + RPMsg transport (openvela nuttx_openamp side;
 *    bare-metal mailbox on the M0 side)
 *  - Fixed 32-byte message slots (no dynamic allocation on M0)
 *  - M0 does NOT run AI: it only wakes, actuates relays and reports
 *    state (planning doc red line)
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef RT_AGENT_INCLUDE_RT_MSG_H
#define RT_AGENT_INCLUDE_RT_MSG_H

#include <stdint.h>

#ifdef __cplusplus
extern "C"
{
#endif

#define RT_MSG_MAGIC        0x52544D31U   /* "RTM1" */
#define RT_MSG_PAYLOAD_MAX  24            /* 32 - 8 header bytes */

enum rt_msg_type
{
  RT_MSG_NONE = 0,

  /* Main -> M0 */
  RT_MSG_RELAY_SET,         /* payload: rt_relay_set_t */
  RT_MSG_RELAY_GET,         /* payload: none; M0 replies RT_MSG_RELAY_STATE */
  RT_MSG_WAKEUP_CFG,        /* payload: rt_wakeup_cfg_t */

  /* M0 -> Main */
  RT_MSG_WAKEUP_EVENT,      /* payload: rt_wakeup_event_t */
  RT_MSG_RELAY_STATE,       /* payload: rt_relay_state_t */
  RT_MSG_ALIVE,             /* payload: none (heartbeat) */

  RT_MSG_TYPE_MAX
};

struct rt_msg_hdr
{
  uint32_t magic;           /* RT_MSG_MAGIC */
  uint16_t type;            /* rt_msg_type */
  uint16_t seq;             /* sender sequence number */
  uint32_t timestamp_ms;    /* sender monotonic ms (best effort) */
};

struct rt_msg
{
  struct rt_msg_hdr hdr;
  uint8_t payload[RT_MSG_PAYLOAD_MAX];
};

/* Relay actuation (main -> M0).  channel maps to the GPIO relay id
 * used by the ai-apps mapping module (lamp id). */
struct rt_relay_set
{
  uint8_t  channel;
  uint8_t  state;           /* 0 = off, 1 = on */
  uint8_t  _pad[2];
  uint32_t flags;           /* reserved */
};

/* Relay state snapshot (M0 -> main). */
struct rt_relay_state
{
  uint8_t  channel;
  uint8_t  state;
  uint8_t  _pad[2];
  uint32_t flags;
};

/* Wake-up event from the AO domain (M0 -> main). */
struct rt_wakeup_event
{
  uint32_t cause;           /* bit0 = relay edge, bit1 = GPIO, ... */
  uint32_t gpio_mask;       /* which GPIOs changed */
};

/* Wake-up configuration (main -> M0): which edges keep the M0 awake. */
struct rt_wakeup_cfg
{
  uint32_t enable_mask;
  uint32_t debounce_ms;
};

/* Shared memory layout (both sides must agree on this).
 * RPMsg vring + this control block, all in a fixed SRAM window. */
struct rt_shared
{
  uint32_t magic;
  uint32_t version;
  volatile uint32_t flags;
  uint8_t  reserved[24];
};

#ifdef __cplusplus
}
#endif

#endif /* RT_AGENT_INCLUDE_RT_MSG_H */

